param([int]$Requests=200,[int]$Concurrency=10,[string]$Url='http://localhost:8080/api/products')
$ErrorActionPreference='Stop';$sw=[Diagnostics.Stopwatch]::StartNew();$results=@(1..$Requests|ForEach-Object -Parallel {$t=[Diagnostics.Stopwatch]::StartNew();try{$r=Invoke-WebRequest -UseBasicParsing $using:Url;[pscustomobject]@{ok=$r.StatusCode-lt400;ms=$t.Elapsed.TotalMilliseconds}}catch{[pscustomobject]@{ok=$false;ms=$t.Elapsed.TotalMilliseconds}}} -ThrottleLimit $Concurrency);$sw.Stop();$a=@($results.ms|Sort-Object);$success=@($results|Where-Object ok).Count;$failed=$Requests-$success;function P($q){$a[[Math]::Min($a.Count-1,[int][Math]::Floor($q*$a.Count))]};[pscustomobject]@{requests=$Requests;success=$success;failed=$failed;seconds=$sw.Elapsed.TotalSeconds;throughput_rps=$Requests/$sw.Elapsed.TotalSeconds;avg_ms=($a|Measure-Object -Average).Average;p50_ms=P .50;p95_ms=P .95;p99_ms=P .99}|Format-List
